/** MSF_REQUEST 단건 조회 **/ SELECT
, TMP_STEP_CD
FROM MSF_REQUEST_TEMP
FROM MSF_REQUEST
WHERE REQUEST_KEY = #{requestKey}
AND TMP_STEP_CD != '4'

/** MSF_REQUEST_CSTMR 단건 조회 **/
SELECT

FROM MSF_REQUEST_CSTMR_TEMP
WHERE REQUEST_KEY = #{requestKey}

/** MSF_REQUEST_AGENT 단건 조회 **/
SELECT

FROM MSF_REQUEST_AGENT_TEMP
WHERE REQUEST_KEY = #{requestKey}

/** MSF_REQUEST_SALE 단건조회 **/
SELECT

FROM MSF_REQUEST_SALE_TEMP
WHERE REQUEST_KEY = #{requestKey}

/** MSF_REQUEST_BILL_REQ 단건조회 **/
SELECT

FROM MSF_REQUEST_BILL_REQ_TEMP
WHERE REQUEST_KEY = #{requestKey}

SELECT

FROM MSF_REQUEST_MOVE_TEMP
WHERE REQUEST_KEY = #{requestKey}

SELECT

FROM MSF_REQUEST_DVC_CHG_TEMP
WHERE REQUEST_KEY = #{requestKey}

SELECT COUNT(1)
FROM MSF_REQUEST_TEMP
WHERE REQUEST_KEY = #{requestKey}

    AND SHOP_CD = #{shopCd}

      AND TMP_STEP_CD = #{tmpStepCd}

SELECT COUNT(1)
FROM MSF_REQUEST_TEMP
WHERE REQUEST_KEY = #{requestKey}
  AND MANAGER_CD = #{managerCd}
  AND TMP_STEP_CD != #{tmpStepCd}

SELECT TMP_STEP_CD
FROM MSF_REQUEST_TEMP
WHERE REQUEST_KEY = #{requestKey}
  AND SHOP_CD = #{shopCd}

SELECT EXISTS (
    SELECT 1
    FROM MSF_REQUEST_TEMP
    WHERE RES_NO = #{resNo}
)

SELECT COUNT(CASE WHEN (PROC_CD = 'CP' or PROC_CD = 'RQ' or PROC_CD = '' or PROC_CD is NULL) THEN 1 END) AS "totalCnt"
    ,COUNT(CASE WHEN (PROC_CD = 'CP') THEN 1 END) AS "openCount"
    ,COUNT(CASE WHEN (PROC_CD = 'RQ' or PROC_CD = '' or PROC_CD is NULL) THEN 1 END) AS "completeCount"
FROM MSF_REQUEST A
WHERE CPNT_ID = #{cpntId}
    AND CNTPNT_SHOP_CD = #{agentCd}
    AND CSTMR_TYPE_CD = #{cstmrTypeCd}
    AND OPER_TYPE_CD = #{operTypeCd}
    AND REQ_IN_DT >= TO_DATE(#{useStartDate}, 'YYYYMMDDHH24MISS')
    AND REQ_IN_DT < TO_DATE(#{useEndDate}, 'YYYYMMDDHH24MISS')
